<?php $__env->startSection('title', 'Detail tiket'); ?>
<?php $__env->startSection('content'); ?>
<section class="page-heading"><div><p class="eyebrow">BOOKING DETAIL</p><h1>Detail tiket</h1><p class="muted">Ringkasan booking dan tindakan operasional.</p></div><a class="button secondary" href="<?php echo e(route('tickets.index')); ?>">← Semua tiket</a></section>
<div class="detail-grid"><section class="panel ticket-card"><div class="ticket-card-top"><div><span class="muted small">KODE BOOKING</span><div class="booking-code"><?php echo e($ticket->booking_code); ?></div></div><span class="status status-<?php echo e($ticket->status); ?>"><?php echo e($ticket->status_label); ?></span></div><div class="ticket-divider"></div><h2><?php echo e($ticket->event->name); ?></h2><p class="muted"><?php echo e($ticket->event->venue); ?> · <?php echo e($ticket->event->starts_at->format('d M Y, H:i')); ?></p><div class="detail-list"><div><span>Nama pembeli</span><strong><?php echo e($ticket->buyer_name); ?></strong></div><div><span>E-mail</span><strong><?php echo e($ticket->buyer_email); ?></strong></div><div><span>Total</span><strong>Rp <?php echo e(number_format((float)$ticket->amount, 0, ',', '.')); ?></strong></div><div><span>Referensi gateway</span><strong><?php echo e($ticket->gateway_reference ?? 'Belum tersedia'); ?></strong></div><div><span>Dibuat</span><strong><?php echo e($ticket->created_at->format('d M Y H:i')); ?></strong></div><div><span>E-tiket diproses</span><strong><?php echo e($ticket->ticket_sent_at?->format('d M Y H:i') ?? 'Belum'); ?></strong></div><div><span>Check-in</span><strong><?php echo e($ticket->checked_in_at?->format('d M Y H:i') ?? 'Belum'); ?></strong></div></div></section>
