<?php if($ticket->status === 'pending'): ?><form method="POST" action="<?php echo e(route('tickets.mark-paid', $ticket)); ?>"><?php echo csrf_field(); ?><button class="button primary full-width" type="submit">Simulasikan pembayaran</button></form><?php endif; ?>
<?php if($ticket->status === 'paid'): ?><form method="POST" action="<?php echo e(route('tickets.send', $ticket)); ?>"><?php echo csrf_field(); ?><button class="button secondary full-width" type="submit">Proses kirim e-tiket</button></form><a class="button secondary full-width" href="<?php echo e(route('validation.form')); ?>">Buka validasi booking</a><?php endif; ?>
<?php if($ticket->status === 'used'): ?><div class="info-note">Tiket telah digunakan pada <?php echo e($ticket->checked_in_at?->format('d M Y H:i')); ?>.</div><?php endif; ?>
